import SwiftUI
import KipurseCore

/// t1034: [zh] are in-app pages (no Safari, no kipurse.com). Same frozen look as build 16.
struct LegalSection: Identifiable { let id = UUID(); let zh: String; let en: String; let bodyZh: [String]; let bodyEn: [String] }

/// Who operates this build and how to reach them. From Info.plist (KIPURSE_OPERATOR_* / KIPURSE_SUPPORT_EMAIL / KIPURSE_GOVERNING_LAW_* in
/// Config/*.xcconfig): the open-source defaults are neutral; the operator's private Config/Local.xcconfig fills in the real values.
enum LegalOperator {
  static func info(_ k: String) -> String {
    let v = ((Bundle.main.object(forInfoDictionaryKey: k) as? String) ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
    return v.contains("$(") ? "" : v
  }
  static var name: String { let n = info("KipurseOperatorName"); return n.isEmpty ? "Kipurse operator" : n }
  static var addrEn: String { info("KipurseOperatorAddressEn") }
  static var addrZh: String { info("KipurseOperatorAddressZh") }
  static var email: String { let e = info("KipurseSupportEmail"); return e.contains("@") ? e : "support@example.com" }
  /// Chinese: "[zh]", or just the name
  static var byZh: String { addrZh.isEmpty ? " \(name)" : "\(addrZh)的 \(name)" }
  /// English: "<name>, <address>", or just the name
  static var nameAddrEn: String { addrEn.isEmpty ? name : "\(name), \(addrEn)" }
  /// Chinese address followed by "[zh]", or ""
  static var addrZhLead: String { addrZh.isEmpty ? "" : "\(addrZh)，" }
  static var contactZh: String { "\(email) · \(name)" + (addrZh.isEmpty ? "" : "，\(addrZh)") }
  static var contactEn: String { "\(email) · \(nameAddrEn)" }
  static var lawZh: String { let j = info("KipurseGoverningLawZh"); return j.isEmpty ? "本条款适用运营方所在地的法律。" : "本条款适用\(j)法律及适用的美国联邦法律。" }
  static var lawEn: String { let j = info("KipurseGoverningLawEn"); return j.isEmpty ? "These Terms are governed by the laws of the operator's place of business." : "These Terms are governed by the laws of \(j) and applicable U.S. federal law." }
}

enum LegalDoc: String, Identifiable {
  case support, privacy, terms
  var id: String { rawValue }
  var titleZh: String { switch self { case .support: return "帮助与客服"; case .privacy: return "隐私政策"; case .terms: return "服务条款" } }
  var titleEn: String { switch self { case .support: return "Help & support"; case .privacy: return "Privacy policy"; case .terms: return "Terms of Service" } }
  var updatedZh: String { switch self { case .support: return "启付帮助"; case .privacy: return "更新日期：2026 年 10 月 23 日"; case .terms: return "更新日期：2026 年 11 月 5 日" } }
  var updatedEn: String { switch self { case .support: return "KIPURSE SUPPORT"; case .privacy: return "LAST UPDATED OCT 23, 2026"; case .terms: return "LAST UPDATED NOV 5, 2026" } }
  var intro: (String, String) {
    switch self {
    case .support: return ("邮箱 \(LegalOperator.email)，一般两个工作日内回复。请不要发送助记词或私钥，我们也绝不会索要。", "Email \(LegalOperator.email). We usually reply within two business days. Never send us your recovery phrase or private keys; we will never ask for them.")
    case .privacy: return ("启付由\(LegalOperator.byZh) 运营。本政策适用于启付 iOS App、启付服务器和 kipurse.com。", "Kipurse (\"we\") is operated by \(LegalOperator.nameAddrEn). This policy covers the Kipurse iOS app, the Kipurse server and kipurse.com.")
    case .terms: return ("本条款是你与 \(LegalOperator.name)（\(LegalOperator.addrZhLead)下称「启付」「我们」）之间的协议，适用于启付 iOS App、启付服务器和 kipurse.com。使用即表示同意；不同意请不要使用。", "These Terms are an agreement between you and \(LegalOperator.nameAddrEn) (\"Kipurse\", \"we\"). They cover the Kipurse iOS app, the Kipurse server and kipurse.com. By using the Service you agree to them. If you do not agree, do not use the Service.")
    }
  }
  var sections: [LegalSection] {
    switch self {
    case .support: return [
      LegalSection(zh: "不靠我们也能取回资金", en: "Get your money out, even without us", bodyZh: ["1. 打开你的 Base Account（Coinbase）。", "2. 撤销启付的花费授权。", "3. 把 USDC 转到任何地方。", "资金一直在你自己的钱包里，启付从不持有。"], bodyEn: ["1. Open your Base Account (Coinbase).", "2. Revoke the Kipurse spend permission.", "3. Send your USDC anywhere.", "Your funds are always in your own wallet. Kipurse never holds them."]),
      LegalSection(zh: "立即停止所有 AI 付款", en: "Stop all AI payments now", bodyZh: ["在 App 的「AI 生活」页点「暂停 AI 付款」，所有 AI 会立刻暂停，随时可以恢复。"], bodyEn: ["In the app, open AI Life and tap Pause AI payments. Every agent stops immediately. You can resume at any time."]),
      LegalSection(zh: "网络费", en: "Network fees", bodyZh: ["网络费只用 USDC 付，按实际成本，启付不加价，确认前就会显示金额，永远不用 ETH。启付不代付、不记欠款。", "开通手续费（已含首次钱包安全上限和 Face ID 批准）：在充值之外另从你的 Coinbase 钱包（Base 账户）扣，不从这次充值里扣。", "日常提现、以后修改钱包安全上限、开户后再开启 Face ID 批准（重装、换手机或开户时没带）：从你的启付钱包余额扣，按实际网络费、确认前显示实时报价。只改上限不会收 Face ID 的费。", "手机丢了用救援页直接取回、一键退回误转的小额：由你的 Coinbase 钱包付。", "启付只支持 Base 主网。"], bodyEn: ["Network fees are paid only in USDC, at actual cost with no Kipurse markup, shown before you confirm, never ETH. Kipurse does not pay them for you and records no debt.", "Opening fee (includes your first wallet safety limits and Face ID approvals): charged from your Coinbase wallet (Base account) on top of your deposit, not taken out of the deposit.", "Everyday withdrawals, later changes to wallet safety limits, and turning Face ID approvals on after opening (reinstall, new phone, or not set up at opening): from your Kipurse wallet balance, at actual network cost with a live quote before you confirm. Changing limits alone never charges a Face ID fee.", "Recovering directly with the rescue page if your phone is lost, and returning a stray small transfer: paid by your Coinbase wallet.", "Kipurse works only on Base mainnet."]),
      LegalSection(zh: "手机丢失或更换", en: "Lost or replaced iPhone", bodyZh: ["用 Base Account 把这台手机从钱包里移除，旧的 Face ID 密钥就会失效。"], bodyEn: ["Remove the phone from your wallet with your Base Account. The old Face ID key stops working."]),
      LegalSection(zh: "删除我的数据", en: "Delete my data", bodyZh: ["在 App 里进入「设置 → 删除账户」。具体删除哪些内容，请看隐私政策。"], bodyEn: ["In the app, go to Settings → Delete account. See the Privacy Policy for what this deletes."]),
    ]
    case .privacy: return [
      LegalSection(zh: "要点", en: "Summary", bodyZh: ["• 我们只收集运行你的钱包所必需的数据。这些数据都与你的钱包地址关联，不用于追踪你。", "• 我们不收集姓名、通讯录或位置。只有你用 Apple Pay 买 USDC 时，才会用到手机号和邮箱（见下文）。没有广告，没有分析 SDK，绝不出售数据。", "• App 里的「删除账户」会清除我们保存的你的全部数据，只保留最基本的财务记账记录（这些记录本来就公开在链上）。"], bodyEn: ["• We collect only what is needed to run your wallet. All of it is linked to your wallet address. None of it is used to track you.", "• We never ask for your name, contacts or location. Your phone number and email are used only if you buy USDC with Apple Pay (see below). There are no ads, no analytics SDKs and no data brokers, and we never sell data.", "• Delete account in the app erases everything we hold about you, except the minimum financial accounting record, which is public on the blockchain anyway."]),
      LegalSection(zh: "收集什么、为什么", en: "What we collect, and why", bodyZh: ["用户 ID：启付钱包地址及其所有者地址（你的 Base Account）；手机 Face ID 签名密钥的公钥（绝不包括私钥）；你连接的 AI：名称、哈希后的令牌、OAuth 授权。用途：识别请求属于哪个钱包，并确认是你本人或你批准的 AI 发出的。", "购买记录：付款的金额、收款方、订单号、时间、交易哈希，以及你加的备注。用途：显示账目、执行限额，并保证同一订单只付一次。", "其他财务信息：你签的限额和期限、信任的收款方、每笔付款的网络费和服务费。用途：执行限额，并在签名前显示费用。", "设备信息：这台 iPhone 的推送令牌，以及 Face ID 签名密钥的 App Attest 密钥 ID。用途：给你发批准请求，并确认请求来自你的手机。", "联系方式（仅 Apple Pay 充值）：如果你用 Apple Pay 买 USDC，我们会把你的手机号和邮箱交给 Coinbase 做它要求的验证，并保存最多 61 天，免得你重复验证。", "客服记录：你对某笔付款「报告问题」时，我们保存你选的原因和补充说明。", "以上数据只用于 App 功能，不用于追踪、广告或画像。不收集：姓名、住址、通讯录、照片、位置、浏览记录、健康数据、广告标识符。服务器日志里没有地址、令牌、IP 或金额。"], bodyEn: ["User ID: your Kipurse wallet address and its owner address (your Base Account); the public key of your iPhone's Face ID signing key (never the private key); identifiers of the AI agents you connect: name, hashed access tokens and OAuth grants. Why: to know which wallet a request belongs to and that you or your approved agent sent it.", "Purchase history: amount, payee, order reference, time, transaction hash and your labels. Why: to show your activity, enforce your limits and pay each order only once.", "Other financial info: the limits and term you signed, your trusted payees, and the network fee and service fee for each payment. Why: to enforce your limits and show the fee before you sign.", "Device information: your iPhone's push-notification token and the App Attest key ID of your Face ID signing key. Why: to send you approval requests and check that requests come from your phone.", "Contact details (Apple Pay top-ups only): if you buy USDC with Apple Pay, we pass your phone number and email to Coinbase for the verification Coinbase requires, and keep them for up to 61 days so you don't have to verify again.", "Support records: when you report a problem with a payment, we keep the reason you chose and your note.", "This data is used only for app functionality, never for tracking, advertising or profiling. Not collected: name, address, contacts, photos, location, browsing history, health data, advertising ID. Server logs contain no wallet addresses, tokens, IP addresses or amounts."]),
      LegalSection(zh: "链上数据", en: "On-chain data", bodyZh: ["启付只运行在 Base 主网。钱包、你签的限额和每一笔付款都是公开链上的交易，任何人都能看到，任何人（包括我们）都无法删除。"], bodyEn: ["Kipurse runs only on Base mainnet. Your wallet, the limits you sign and every payment are public blockchain transactions. Anyone can see them, and nobody, including us, can delete them."]),
      LegalSection(zh: "你的钱", en: "Your money", bodyZh: ["• 启付不托管资金。USDC 一直在你自己的钱包里，你随时可以用 Base Account 取出，不依赖我们。", "• 服务器只能在你链上签过的限额内付款。没有你手机的签名，它不能添加收款方，也不能改限额或阻止你取款。", "• 启付不设备付金，不代付网络费。网络费只用 USDC 由你自己付，签名前就会显示金额。"], bodyEn: ["• Kipurse is non-custodial. Your USDC stays in your own wallet, and you can always withdraw with your Base Account, even without us.", "• Our server can only pay within the limits you signed on chain. It cannot add a payee without your phone's signature, change your limits or block withdrawals.", "• Kipurse keeps no reserve and does not pay network fees for you. You pay your own network fee in USDC, shown before you sign."]),
      LegalSection(zh: "共享", en: "Sharing", bodyZh: ["我们不出售、不出租数据，只在以下情况共享：把你授权的交易提交到 Base 链上；Cloudflare 负责传输加密流量；法律要求时提供给有关机构。", "Base Account 由 Coinbase 提供，适用其隐私政策。你连接的 AI 助手只会收到通过启付请求的内容，适用其各自的政策。"], bodyEn: ["We do not sell or rent data. We share it only with the Base blockchain (the transactions you authorize), Cloudflare (encrypted traffic to our server), and authorities if the law requires it.", "Your Base Account is provided by Coinbase under its own privacy policy. AI assistants you connect receive only what is requested through Kipurse, under their own policies."]),
      LegalSection(zh: "安全与保存", en: "Security and retention", bodyZh: ["数据按用户分别加密保存，全部传输都使用 TLS。在你删除之前，我们会一直保存。"], bodyEn: ["Records are encrypted at rest with a separate key per user. All traffic uses TLS. We keep your records until you delete them."]),
      LegalSection(zh: "删除我的数据", en: "Delete my data", bodyZh: ["在 App 里进入「设置 → 删除账户」，会永久删除服务器上的钱包记录、AI、令牌、OAuth 授权、备注、规则和手机公钥，以及 App 本地存储、钥匙串和 Siri/Spotlight 数据。", "只保留与链上交易对应的服务费和网络费记账行，这些本来就公开在链上。要彻底结束链上授权，请用 Base Account 撤销启付的花费授权。你也可以发邮件申请删除。"], bodyEn: ["In the app, go to Settings → Delete account. This permanently erases your wallet record, agents, tokens, OAuth grants, labels, rules and phone key from our server, plus the app's storage, Keychain items and Siri/Spotlight data.", "Only the fee and network-fee accounting rows tied to on-chain transactions remain; they are public on the blockchain anyway. To end on-chain access entirely, revoke the Kipurse spend permission with your Base Account. You can also email us to request deletion."]),
      LegalSection(zh: "网站", en: "Website", bodyZh: ["kipurse.com 没有追踪 Cookie，也没有统计分析，只在浏览器里记住你选的语言。你给我们发邮件时，邮箱只用于回复你。"], bodyEn: ["kipurse.com sets no tracking cookies and has no analytics. It saves only your language choice. If you email us, we use your address only to reply."]),
      LegalSection(zh: "未成年人", en: "Children", bodyZh: ["启付不面向 18 岁以下用户。"], bodyEn: ["Kipurse is not intended for anyone under 18."]),
      LegalSection(zh: "变更与联系", en: "Changes and contact", bodyZh: ["政策有变更时，我们会在 App 内公布并更新日期。联系：\(LegalOperator.contactZh)"], bodyEn: ["We will post changes in the app and update the date above. Contact: \(LegalOperator.contactEn)"]),
    ]
    case .terms: return [
      LegalSection(zh: "1. 启付是什么", en: "1. What Kipurse is", bodyZh: ["• 启付是不托管资金的软件：让你在 Base 链上自己的智能钱包里设置链上花费限额，你连接的 AI 可以在限额内用 USDC 付款。", "• 我们从不持有你的资金或私钥。钱包由你自己的 Base Account（Coinbase 提供）和 iPhone 的 Face ID 签名密钥控制。", "• 启付不是银行、券商、交易所、汇款机构或投资顾问；钱包里的 USDC 不是存款，不受 FDIC 或任何政府机构保险。"], bodyEn: ["• Kipurse is non-custodial software. It lets you set on-chain spending limits on your own smart wallet on Base, so AI assistants you connect can pay in USDC within those limits.", "• We never hold your funds or your private keys. Your wallet is controlled by your own Base Account (provided by Coinbase) and your iPhone's Face ID signing key.", "• Kipurse is not a bank, broker, exchange, money transmitter or investment adviser. USDC in your wallet is not a deposit and is not insured by the FDIC or any government agency."]),
      LegalSection(zh: "2. 使用资格", en: "2. Eligibility", bodyZh: ["• 仅限 18 岁以上成年人。你必须先开通 Coinbase 账户并完成 Coinbase 实名认证（KYC），启付依赖 Coinbase 完成身份和年龄验证。开通新钱包前，你使用的 Base Account 必须带有 Coinbase 链上「Coinbase Verified Account」认证。启付只读取这一公开认证，自己不做实名认证，不收集身份证件或身份数据。", "• 如果你在美国制裁名单（包括 OFAC SDN 名单）上，或由名单上的人拥有或控制，或位于受美国全面制裁的国家或地区，不得使用本服务。", "• 用 Apple Pay 或银行卡购买 USDC 由 Coinbase 提供，仅在 Coinbase 支持的地区可用。"], bodyEn: ["• Kipurse is for adults (18+) only. You must first open a Coinbase account and pass Coinbase's identity verification (KYC); Kipurse relies on Coinbase for identity and age verification. Before a new wallet can be opened, your Base Account must carry Coinbase's on-chain \"Coinbase Verified Account\" attestation. Kipurse only reads that public attestation and does no identity verification of its own and collects no identity documents or data.", "• You may not use the Service if you are on, or owned or controlled by someone on, a U.S. sanctions list (including the OFAC SDN list), or if you are located in a country or region under comprehensive U.S. sanctions.", "• Buying USDC with Apple Pay or a card is provided by Coinbase and is available only where Coinbase offers it."]),
      LegalSection(zh: "3. 你的钱包、你的密钥、你的责任", en: "3. Your wallet, your keys, your responsibility", bodyZh: ["• 你自己负责 Base Account、iPhone 和 Face ID。如果丢失，我们无法恢复你的钱包或资金。", "• 即使本服务不可用，你也始终可以用 Base Account 取回资金。", "• 链上交易是最终且不可撤销的。付款上链后，我们无法取消、撤回或退款。"], bodyEn: ["• You are solely responsible for your Base Account, your iPhone and your Face ID. If you lose them, we cannot recover your wallet or your funds.", "• You can always withdraw your funds with your Base Account, even if the Service is unavailable.", "• Blockchain transactions are final and irreversible. We cannot cancel, reverse or refund a payment once it is on chain."]),
      LegalSection(zh: "4. 限额与 AI", en: "4. Limits and AI agents", bodyZh: ["• 限额（单笔、每天、总额和期限）由你自己定，启付不设上限。", "• 在你的限额内，你连接的 AI 付的款视为你本人授权。请选择即使 AI 出错或被滥用你也能承受的限额。", "• 新收款方需要你用手机 Face ID 批准，除非你已信任它。你可以随时暂停任何 AI、撤销授权或取回全部资金。", "• AI 助手是第三方服务，适用其各自条款。我们不对它们决定买什么、或商家出售的商品和服务负责。"], bodyEn: ["• You choose your own spending limits (per payment, per day, total and term). Kipurse does not impose a maximum on the limits you choose.", "• Within your limits, payments made by an agent you connected are treated as authorized by you. Choose limits you are comfortable losing if an agent makes a mistake or is misused.", "• New payees require approval with your phone's Face ID unless you have trusted them. You can pause any agent, revoke its access, or withdraw everything at any time.", "• AI assistants are third-party services under their own terms. We are not responsible for what they decide to buy or for the goods and services sold by merchants."]),
      LegalSection(zh: "5. 付款、商家与协议", en: "5. Payments, merchants and protocols", bodyZh: ["• 启付可以付款给在 Base 上收 USDC 的商家，包括通过开放的 x402 支付协议和 AP2 授权。商家是独立第三方，商品或服务的纠纷由你与商家解决。", "• 不提供托管。启付目前不托管付款，也不提供买家保护、争议处理或拒付。"], bodyEn: ["• Kipurse can pay merchants that accept USDC on Base, including through the open x402 payment protocol and Agent Payments Protocol (AP2) mandates. Merchants are independent third parties; disputes about goods or services are between you and the merchant.", "• Escrow is not offered. Kipurse does not hold payments in escrow or offer buyer protection, dispute resolution or chargebacks."]),
      LegalSection(zh: "6. 费用", en: "6. Fees", bodyZh: ["• 启付对经由它的每笔付款收取 0.1% 服务费，签名前显示。", "• 网络费（包括开户网络费）由你用 USDC 从自己的钱包余额支付，按实际花费扣，签名前显示。启付不代付、不记欠款。", "• Coinbase 购买 USDC 可能另收费用。", "• 费用调整会提前至少 30 天在 App 内通知，不影响你已签名的付款。"], bodyEn: ["• Kipurse charges a service fee of 0.1% of each payment made through it, shown before you sign.", "• Network fees, including the account-opening network fee, are paid by you in USDC from your own wallet balance at actual cost and shown before you sign. Kipurse does not pay them for you and records no debt.", "• Coinbase may charge its own fees for USDC purchases.", "• We may change fees with at least 30 days' notice in the app; changes never apply to payments you already signed."]),
      LegalSection(zh: "7. 制裁与合规筛查", en: "7. Sanctions and compliance screening", bodyZh: ["• 为遵守美国法律，启付会将钱包地址（你的、收款方和提现目标）与美国制裁数据、链上制裁预言机和公开的诈骗地址名单比对。", "• 匹配的付款会被拒绝。由于不托管，我们无法冻结你钱包里的资金，但可能停止向你提供服务，并按法律要求报告。筛查尽力而为，不保证交易对手合法或安全。"], bodyEn: ["• To comply with U.S. law, Kipurse screens wallet addresses (yours, payees and withdrawal destinations) against U.S. sanctions data, on-chain sanctions oracles and public lists of known scam addresses.", "• We will refuse a payment that matches. Because we are non-custodial we cannot freeze funds in your wallet, but we may stop providing the Service to you and report as required by law. Screening is best-effort and does not guarantee a counterparty is lawful or safe."]),
      LegalSection(zh: "8. 可接受的使用", en: "8. Acceptable use", bodyZh: ["你不得利用本服务违反任何法律（包括制裁、反洗钱、消费者保护或出口法律），购买非法商品或服务，欺诈他人，或干扰、攻击、逆向工程本服务（开源许可允许的除外）。"], bodyEn: ["You will not use the Service to violate any law, including sanctions, anti-money-laundering, consumer-protection or export laws; to buy illegal goods or services; to defraud anyone; or to interfere with, attack or reverse-engineer the Service other than as allowed by its open-source licenses."]),
      LegalSection(zh: "9. 开源软件", en: "9. Open-source software", bodyZh: ["启付部分代码以开源许可发布（Apache-2.0；网关为 AGPL-3.0），这些代码的使用适用相应许可。本条款适用托管服务。"], bodyEn: ["Parts of Kipurse are published under open-source licenses (Apache-2.0, and AGPL-3.0 for the gateway). Those licenses govern that code. These Terms govern the hosted Service."]),
      LegalSection(zh: "10. 风险", en: "10. Risks", bodyZh: ["你理解：智能合约可能有漏洞；启付合约和服务器尚未经过独立审计；USDC 依赖发行方 Circle，可能脱锚或被发行方冻结；Base 网络可能拥堵、停止或变更；AI 可能出错；数字资产相关法律可能变化。"], bodyEn: ["You understand that smart contracts may have bugs; the Kipurse contracts and server have not been independently audited; USDC depends on its issuer (Circle) and may lose its peg or be frozen; the Base network may be congested, halted or changed; AI agents can make mistakes; and laws on digital assets may change."]),
      LegalSection(zh: "11. 免责声明", en: "11. Disclaimers", bodyZh: ["在法律允许的最大范围内，本服务按「现状」和「可用」提供，不作任何明示或默示保证，包括适销性、特定用途适用性和不侵权。"], bodyEn: ["THE SERVICE IS PROVIDED \"AS IS\" AND \"AS AVAILABLE\", WITHOUT WARRANTIES OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NON-INFRINGEMENT, TO THE FULLEST EXTENT PERMITTED BY LAW."]),
      LegalSection(zh: "12. 责任限制", en: "12. Limitation of liability", bodyZh: ["在法律允许的最大范围内，启付不对任何间接、附带、特殊、后果性或惩罚性损害负责，也不对因你的限额、你的 AI、商家、第三方服务、区块链或你丢失密钥造成的资金损失负责。我们的总责任以索赔前 12 个月你支付给我们的服务费或 100 美元两者中较高者为限。"], bodyEn: ["TO THE FULLEST EXTENT PERMITTED BY LAW, KIPURSE WILL NOT BE LIABLE FOR ANY INDIRECT, INCIDENTAL, SPECIAL, CONSEQUENTIAL OR PUNITIVE DAMAGES, OR FOR LOST FUNDS CAUSED BY YOUR LIMITS, YOUR AGENTS, MERCHANTS, THIRD-PARTY SERVICES, THE BLOCKCHAIN OR YOUR LOSS OF KEYS. OUR TOTAL LIABILITY IS LIMITED TO THE GREATER OF THE SERVICE FEES YOU PAID US IN THE 12 MONTHS BEFORE THE CLAIM OR US$100."]),
      LegalSection(zh: "13. 赔偿", en: "13. Indemnity", bodyZh: ["因你滥用本服务或违反本条款或法律而引起的第三方索赔，由你向我们赔偿。"], bodyEn: ["You will indemnify us against third-party claims arising from your misuse of the Service or violation of these Terms or the law."]),
      LegalSection(zh: "14. 暂停与终止", en: "14. Suspension and termination", bodyZh: ["你可以随时停止使用，并在 App 里删除数据（设置 → 删除账户）。如法律要求、制裁匹配或严重违规，我们可能暂停或终止向你提供服务。无论哪种情况，你都可以通过 Base Account 在链上取回资金。"], bodyEn: ["You may stop using the Service at any time and delete your data in the app (Settings → Delete account). We may suspend or end the Service for you if required by law, for sanctions matches, or for serious violations. You keep access to your funds on chain through your Base Account in every case."]),
      LegalSection(zh: "15. 适用法律", en: "15. Governing law", bodyZh: [LegalOperator.lawZh], bodyEn: [LegalOperator.lawEn]),
      LegalSection(zh: "16. Apple", en: "16. Apple", bodyZh: ["如果你从 App Store 获得本 App：本条款是你与启付之间的协议，而非与 Apple。Apple 没有义务提供支持或维护，也不对与本 App 有关的索赔负责。Apple 及其子公司是本条款的第三方受益人，可以执行本条款。"], bodyEn: ["If you got the app from the App Store: these Terms are between you and Kipurse, not Apple. Apple has no obligation to provide support or maintenance and is not responsible for claims about the app. Apple and its subsidiaries are third-party beneficiaries of these Terms and may enforce them."]),
      LegalSection(zh: "17. 变更", en: "17. Changes", bodyZh: ["我们可能更新本条款，会在 App 内公布新版本并更新日期；重大变更生效前会在 App 内通知你。"], bodyEn: ["We may update these Terms. We will post the new version in the app, update the date above, and tell you in the app about material changes before they take effect."]),
      LegalSection(zh: "18. 联系", en: "18. Contact", bodyZh: [LegalOperator.contactZh], bodyEn: [LegalOperator.contactEn]),
    ]
    }
  }
}

struct LegalPageView: View {
  let doc: LegalDoc
  var body: some View {
    ScrollView {
      VStack(alignment: .leading, spacing: KP.Space.cardGap) {
        PageTitle(eyebrow: T(doc.updatedZh, doc.updatedEn), title: T(doc.titleZh, doc.titleEn), id: "legal.\(doc.rawValue).title")
        Text(T(doc.intro.0, doc.intro.1)).font(KP.Typo.body).foregroundStyle(.secondary).fixedSize(horizontal: false, vertical: true)
        if doc == .support {
          Link(destination: URL(string: "mailto:\(LegalOperator.email)") ?? URL(string: "mailto:")!) {
            Label(T("发邮件给客服", "Email support"), systemImage: "envelope.fill").font(KP.Typo.button).foregroundStyle(.white)
              .frame(maxWidth: .infinity, minHeight: KP.buttonHeight)
              .background(KP.brandGradient, in: RoundedRectangle(cornerRadius: KP.Radius.control, style: .continuous))
          }.accessibilityIdentifier("legal.support.mail")
        }
        ForEach(doc.sections) { sec in
          VStack(alignment: .leading, spacing: KP.Space.xs) {
            Text(T(sec.zh, sec.en)).font(KP.Typo.cardTitle)
            ForEach(Array((Loc.isChinese ? sec.bodyZh : sec.bodyEn).enumerated()), id: \.offset) { _, p in
              Text(p).font(KP.Typo.body).foregroundStyle(.secondary).fixedSize(horizontal: false, vertical: true)
            }
          }.frame(maxWidth: .infinity, alignment: .leading).padding(KP.Space.m).glass()
        }
      }.padding(.horizontal, KP.Space.page).padding(.bottom, 132)
    }
    .background(MockBG())
    .navigationBarTitleDisplayMode(.inline)
    .accessibilityIdentifier("legal.\(doc.rawValue)")
  }
}
